    let mut result = HashSet::new();

    for active_overlay in self.active_overlays.iter() {
        if let Some(env_vars) = engine_state.env_vars.get(active_overlay) {
            result.extend(
                env_vars
                    .keys()
                    .filter(|k| {
                        if let Some(env_hidden) = self.env_hidden.get(active_overlay) {
